import {catalog,calculateBudget,monthsBefore,yen,escapeHTML as esc} from './core.js';
const colors=['#c2d8a9','#93b69a','#718c6a','#c5b995'];
const field=(label,html,full=false)=>`<label class="field${full?' full':''}"><span>${label}</span>${html}</label>`;
const select=(name,options,value)=>`<select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`}).join('')}</select>`;
const num=(name,value,min=0,max=10000000,step=1000)=>`<input name="${name}" type="number" min="${min}" max="${max}" step="${step}" value="${esc(value)}" required>`;
const text=(name,value='',placeholder='')=>`<input name="${name}" value="${esc(value)}" placeholder="${esc(placeholder)}" maxlength="300">`;
const note=t=>`<p class="card-note">${t}</p>`;
const btn=(label,cls='secondary',attrs='')=>`<button type="button" class="${cls}" ${attrs}>${label}</button>`;
const validNum=(el,fallback)=>Number.isFinite(el.valueAsNumber)&&el.checkValidity()?el.valueAsNumber:fallback;
const el=(tag,cls,html)=>{const n=document.createElement(tag);n.className=cls;if(html!==undefined)n.innerHTML=html;return n;};
export function createCard(id,ctx){const c=catalog.find(c=>c.id===id);const root=el('article','card');root.dataset.card=id;root.innerHTML=`<header class="card-head"><div><div class="card-kicker">GUIGU / ${esc(c.tag)}</div><h2>${esc(c.label)}</h2></div><span class="serial">${String(catalog.indexOf(c)+1).padStart(2,'0')} / 12</span></header><div class="card-body"></div>`;const body=root.querySelector('.card-body');const action=(html)=>{const n=el('div','card-actions',html);root.append(n);return n;};const follow=(labels)=>{const n=el('div','followups');labels.forEach(([label,id])=>{const b=el('button','',esc(label));b.type='button';b.onclick=()=>ctx.launch(id,label);n.append(b)});root.append(n);};({visa,draft,budget,flight,housing,schools,compare,reviews,timeline,profile,chart,dictionary}[id])({root,body,action,follow,...ctx});return root;}
function visa({body,action,follow,toast}){
 const stages=[['学校与材料','先向目标学校确认招生要求和材料清单。录取、在留资格和签证是不同步骤。'],['在留资格 COE','COE 是入境活动符合相应条件的证明，通常由日本境内代理人办理；它本身不是签证，也不保证获签。'],['递交签证','按照管辖使领馆的要求准备护照、申请表、照片及 COE 等材料。具体补件以官方要求为准。']];
 body.innerHTML=`<div class="step-pills">${stages.map(([s],i)=>btn(s,i?'':'active',`data-stage="${i}"`)).join('')}</div><div class="mechanism"></div><h3 class="subheading">先把准备状态记下来</h3>${['确认目标学校的申请材料','检查护照有效期与个人信息','向学校确认 COE 办理安排','核对管辖使领馆的签证要求'].map(t=>`<label class="check-row"><input type="checkbox"><span>${t}</span></label>`).join('')}<div class="check-progress"><i style="width:0%"></i></div><p class="card-note" data-progress>0 / 4 项已准备</p>${note('这是机制概览，不代替你的具体申请要求。<a target="_blank" rel="noopener" href="https://www.mofa.go.jp/j_info/visit/visa/long/visa6.html">日本外务省 · 留学签证 ↗</a>')}`;
 const show=i=>{body.querySelector('.mechanism').textContent=stages[i][1];body.querySelectorAll('[data-stage]').forEach((b,j)=>b.classList.toggle('active',i===j));};show(0);body.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>show(+b.dataset.stage));body.onchange=()=>{const n=body.querySelectorAll('input:checked').length;body.querySelector('.check-progress i').style.width=n/4*100+'%';body.querySelector('[data-progress]').textContent=`${n} / 4 项已准备`;};follow([['整理我的申请理由','draft'],['把步骤放进时间线','timeline']]);
}
function draft({body,action,follow,state,toast}){
 body.innerHTML=`<form class="draft-form"><div class="fields">${field('申请学校',text('school','','填写目标学校'))}${field('当前背景',text('background',state.profile.background||'','例如：本科毕业，正在学习日语'))}${field('为什么想去日本？',`<textarea name="reason" required maxlength="1500" placeholder="写下真实原因，不用一开始就写得很正式。"></textarea>`,true)}${field('学习计划与未来目标',`<textarea name="goal" required maxlength="1500" placeholder="想学什么，希望达到什么水平，之后想做什么？">${esc(state.profile.goal||'')}</textarea>`,true)}</div><p class="card-note">预览版会按你的输入组合结构化草稿，不补写不存在的经历。正式文件请按学校或使领馆要求调整。</p><button class="primary" style="margin-top:16px">整理成第一稿 ↗</button></form><div class="output-box" hidden></div>`;
 body.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const school=f.get('school').trim()||'目标学校';const output=`留学申请理由书 · 草稿\n\n一、个人背景\n${f.get('background')||'［待补充：目前学历、学习或工作经历］'}\n\n二、留学动机\n${f.get('reason')}\n\n三、学习计划与未来目标\n${f.get('goal')}\n\n四、申请意向\n希望申请${school}，并根据学校的实际课程安排进一步完善学习计划。\n\n［待核实：课程名称、学习期限、经费安排及提交格式］`;body.querySelector('.output-box').hidden=false;body.querySelector('.output-box').textContent=output;const a=action(btn('复制草稿','secondary','data-copy')+btn('下载文本','secondary','data-download'));a.querySelector('[data-copy]').onclick=()=>copy(output,toast);a.querySelector('[data-download]').onclick=()=>download('留学申请草稿.txt',output);e.target.querySelector('button').textContent='更新草稿 ↗';if(body.parentNode.querySelectorAll('.card-actions').length>1)body.parentNode.querySelector('.card-actions').remove();};follow([['核对签证准备事项','visa']]);
}
function budget({body,follow,state,query,bus}){
 // Extract only explicit monthly rent, not arbitrary numbers.
 const rent=/房租\s*(\d+(?:\.\d+)?)\s*(万|千)?/.exec(query);if(rent)state.budget.rent=Math.min(200000,+rent[1]*(rent[2]==='万'?10000:rent[2]==='千'?1000:1));
 const b=state.budget;
 body.innerHTML=`<div class="metric-row"><div><div class="metric-label">${b.months} 个月 · 预计合计</div><div class="big-number" data-total></div><div class="metric-secondary" data-cny></div></div><span class="tiny-tag">可调整的假设</span></div><div class="budget-bar"></div><div class="legend"></div><div class="fields" style="margin-top:25px">${field('学费 / 日元',num('tuition',b.tuition,0,5000000))}${field('初期费用 / 日元',num('setup',b.setup,0,3000000))}${field('每月房租',`<input type="range" name="rent" min="20000" max="150000" step="1000" value="${b.rent}"><div class="range-row"><span>¥20,000</span><output data-rent></output><span>¥150,000</span></div>`)}${field('每月生活费（不含房租）',`<input type="range" name="living" min="20000" max="120000" step="1000" value="${b.living}"><div class="range-row"><span>¥20,000</span><output data-living></output><span>¥120,000</span></div>`)}${field('计划月数',num('months',b.months,1,36,1))}${field('换算假设 / 1 日元 = 人民币',num('rate',b.rate,.001,1,.001))}</div>${note('默认值仅用于交互试算，不是学校报价或实时汇率。初期费用可计入机票、押金与安置费用。<a href="https://www.studyinjapan.go.jp/en/life/cost-of-living/" target="_blank" rel="noopener">查看 JASSO 生活费参考 ↗</a>')}`;
 const refresh=()=>{const {total,cny,parts}=calculateBudget(state.budget);body.querySelector('[data-total]').textContent=yen(total);body.querySelector('[data-cny]').textContent=`约人民币 ¥${Math.round(cny).toLocaleString()} · 按你设置的换算值`;body.querySelector('.metric-label').textContent=`${state.budget.months} 个月 · 预计合计`;body.querySelector('[data-rent]').textContent=yen(state.budget.rent);body.querySelector('[data-living]').textContent=yen(state.budget.living);body.querySelector('.budget-bar').innerHTML=parts.map((p,i)=>`<i style="width:${total?p.value/total*100:0}%;background:${colors[i]}"></i>`).join('');body.querySelector('.legend').innerHTML=parts.map((p,i)=>`<span><i style="background:${colors[i]}"></i>${p.label}</span>`).join('');};refresh();body.oninput=e=>{if(e.target.name){state.budget[e.target.name]=validNum(e.target,state.budget[e.target.name]);refresh();bus.dispatchEvent(new CustomEvent('budget',{detail:{source:body}}));}};bus.addEventListener('budget',e=>{if(e.detail?.source===body)return;body.querySelectorAll('input').forEach(n=>{if(n.name in state.budget)n.value=state.budget[n.name];});refresh();});follow([['换成图表看一眼','chart'],['估算租房初期费用','housing']]);
}
function flight({body,action,state,toast}){
 body.innerHTML=`<form><div class="fields">${field('从哪里出发',text('from','','例如：上海'))}${field('抵达城市',select('to',['东京','大阪','名古屋','福冈'],state.profile.city||'东京'))}${field('计划出发日期','<input type="date" name="date" required>')}${field('托运行李偏好',select('bags',['1 件托运','2 件托运','暂不确定']))}${field('路线偏好',select('route',['优先直飞','接受一次中转','价格优先']))}${field('可调整天数',select('flex',['固定日期','前后 3 天','前后 7 天']))}</div><button class="primary" style="margin-top:18px">生成出发需求卡 ↗</button></form><div class="output-box" hidden></div><h3 class="subheading">订票前核对</h3>${['确认签证及学校报到安排','核对机场、抵达时刻和交通','确认托运行李、退改签与总价'].map(t=>`<label class="check-row"><input type="checkbox"><span>${t}</span></label>`).join('')}${note('尚未连接航班数据；这里整理查询条件，不展示虚构航班、库存或票价。')}`;
 body.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const out=`${f.get('from')||'出发地待定'} → ${f.get('to')}\n出发日期：${f.get('date')}（${f.get('flex')}）\n路线：${f.get('route')} · 行李：${f.get('bags')}\n\n下一步：在航司官网核对对应日期的实际航班、行李额度和退改条件。`;const o=body.querySelector('.output-box');o.hidden=false;o.textContent=out;toast('出发条件已整理');};
}
function housing({body,follow,state}){
 let type='学生宿舍';body.innerHTML=`<div class="segmented">${['学生宿舍','合租','独居'].map((t,i)=>btn(t,i?'':'active',`data-type="${t}"`)).join('')}</div><div class="mechanism" data-hint>先向学校确认是否提供宿舍、入住期限和费用构成。</div><div class="metric-row" style="margin-top:22px"><div><div class="metric-label">预计首次支付（日元）</div><div class="big-number" data-total></div></div><span class="tiny-tag" data-mode>学生宿舍</span></div><div class="fields">${field('月租 / 日元',num('rent',state.budget.rent,0,500000))}${field('押金 / 几个月房租',num('deposit',1,0,6,.5))}${field('礼金 / 几个月房租',num('gift',0,0,6,.5))}${field('其它一次性费用 / 日元',num('other',50000,0,1000000))}</div><div class="output-box" data-breakdown></div>${note('试算公式：首月租金 + 押金 + 礼金 + 其它费用。所有数值可改，不代表真实房源；管理费、担保费等请核对合同。')}`;
 const refresh=()=>{const data=Object.fromEntries([...body.querySelectorAll('input')].map(n=>[n.name,Math.max(0,n.valueAsNumber||0)]));const total=data.rent*(1+data.deposit+data.gift)+data.other;body.querySelector('[data-total]').textContent=yen(total);body.querySelector('[data-breakdown]').textContent=`${type} · 首月 ${yen(data.rent)} + 押金 ${yen(data.rent*data.deposit)} + 礼金 ${yen(data.rent*data.gift)} + 其它 ${yen(data.other)}`;};body.oninput=refresh;body.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;body.querySelectorAll('[data-type]').forEach(x=>x.classList.toggle('active',x===b));body.querySelector('[data-mode]').textContent=type;body.querySelector('[data-hint]').textContent=({'学生宿舍':'先向学校确认是否提供宿舍、入住期限和费用构成。','合租':'除了租金，还需核对公共空间、室友安排、合约期限与生活规则。','独居':'把通学时间与首次支付金额一起考虑，再逐项核对租约费用。'})[type];refresh();});refresh();follow([['把住宿放进整体预算','budget'],['敷金、礼金是什么意思？','dictionary']]);
}
function schoolOptions(list){return list.map(s=>[s.id,s.name]);}
function schools({body,follow,state,schoolData,query}){
 const cities=[...new Set(schoolData.map(s=>s.city))];const inferred=cities.find(c=>query.includes(c));body.innerHTML=`<div class="fields">${field('所在城市',select('city',[['','全部城市'],...cities],inferred||state.profile.city||''))}${field('搜索校名 / 街区',text('filter','','例如：早稻田、高田马场'))}</div><div class="results-list"></div><div class="school-detail" hidden></div>${note('来自项目已有的 53 所学校资料，地址与交通仍需核实。点击学校查看详细地址与资料来源。')}`;
 const detail=s=>{const d=body.querySelector('.school-detail');d.hidden=false;d.innerHTML=`<h3>${esc(s.name)}</h3><div>${esc(s.japaneseName)}</div><div>${esc(s.address||'地址待核实')}</div><div>交通：${esc(s.access||'待核实')}</div>${s.note?`<div>${esc(s.note)}</div>`:''}<div style="margin-top:10px"><a href="${esc(s.source)}" target="_blank" rel="noopener">核对学校资料 ↗</a>${s.coordinates?`　<a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.address)}" target="_blank" rel="noopener">打开地图 ↗</a>`:''}</div>`;};
 const refresh=()=>{const city=body.querySelector('[name=city]').value,q=body.querySelector('[name=filter]').value.trim().toLowerCase();const list=schoolData.filter(s=>(!city||s.city===city)&&(!q||(s.name+s.japaneseName+s.district).toLowerCase().includes(q)));const r=body.querySelector('.results-list');r.replaceChildren();if(!list.length){r.innerHTML='<div class="empty-state">没有匹配学校，试试切换城市或简化校名。</div>';body.querySelector('.school-detail').hidden=true;return;}list.forEach(s=>{const b=el('button','school-row',`<span>⌖</span><span><strong>${esc(s.name)}</strong><small>${esc(s.city)} · ${esc(s.district)}</small></span>`);b.type='button';b.onclick=()=>{r.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));detail(s);};r.append(b)});detail(list[0]);};body.querySelector('[name=city]').onchange=refresh;body.querySelector('[name=filter]').oninput=refresh;refresh();follow([['挑两所并排比较','compare']]);
}
function compare({body,follow,schoolData,state,toast}){
 body.innerHTML=`<div class="fields">${field('学校 A',select('a',schoolOptions(schoolData),schoolData[0].id))}${field('学校 B',select('b',schoolOptions(schoolData),schoolData[1].id))}</div><div class="table-wrap"></div><label class="field full" style="margin-top:18px"><span>我的选择理由</span><textarea name="note" placeholder="例如：我更看重通学距离，学费还需要核实。"></textarea></label><div style="margin-top:14px">${btn('更偏向 A','secondary','data-pick="a"')} ${btn('更偏向 B','secondary','data-pick="b"')}</div>${note('只比较已有资料。学费、课程与入学条件没有经核实的数据时，明确保留为待核实。')}`;
 const refresh=()=>{const a=schoolData.find(s=>s.id===body.querySelector('[name=a]').value),b=schoolData.find(s=>s.id===body.querySelector('[name=b]').value);body.querySelector('.table-wrap').innerHTML=`<table><thead><tr><th>对比维度</th><th>${esc(a.name)}</th><th>${esc(b.name)}</th></tr></thead><tbody>${[['城市',a.city,b.city],['街区',a.district,b.district],['交通',a.access||'待核实',b.access||'待核实'],['地址',a.address||'待核实',b.address||'待核实'],['学费 / 招生','待核实','待核实']].map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}<tr><td>来源</td><td><a href="${esc(a.source)}" target="_blank" rel="noopener">学校资料 ↗</a></td><td><a href="${esc(b.source)}" target="_blank" rel="noopener">学校资料 ↗</a></td></tr></tbody></table>`;};body.querySelectorAll('select').forEach(s=>s.onchange=refresh);refresh();body.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{const s=schoolData.find(s=>s.id===body.querySelector(`[name=${b.dataset.pick}]`).value);state.shortlist.add(s.id);toast(`已记下偏好：${s.name}`);b.textContent='已记下 ✓';});follow([['给候选学校做个人评估','reviews']]);
}
function reviews({body,schoolData,toast,state}){
 body.innerHTML=`${field('评价对象',select('school',schoolOptions(schoolData),[...state.shortlist][0]||schoolData[0].id))}<p class="card-note">这是你的个人评估表，不是学生口碑或平台评分。尚不了解的维度可以保持“待了解”。</p>${['课程匹配','通学便利','费用透明','升学支持'].map((t,i)=>`<label class="rating-row"><span>${t}</span><input type="range" min="0" max="5" value="0" step="1" name="score${i}" aria-label="${t}"><output>待了解</output></label>`).join('')}<div class="fields">${field('信息来源',text('source','','学校官网、说明会或访谈日期'),true)}${field('依据与待核实问题','<textarea name="evidence" maxlength="2000" placeholder="写下具体事实，例如：官网是否公开退费条款？"></textarea>',true)}</div><button class="primary" data-save style="margin-top:16px">保存本次评估</button><div class="output-box" hidden></div>`;
 body.querySelectorAll('input[type=range]').forEach(i=>i.oninput=()=>i.nextElementSibling.textContent=+i.value?i.value+'/5':'待了解');body.querySelector('[data-save]').onclick=()=>{const name=body.querySelector('select').selectedOptions[0].textContent;const scores=[...body.querySelectorAll('.rating-row')].map(r=>r.children[0].textContent+'：'+r.querySelector('output').textContent);const out=`${name} · 我的评估\n${scores.join('　')}\n来源：${body.querySelector('[name=source]').value||'尚未填写'}\n依据：${body.querySelector('textarea').value||'待补充具体依据'}`;const box=body.querySelector('.output-box');box.hidden=false;box.textContent=out;toast('评估已保留在当前对话');};
}
function timeline({body,action,state,toast}){
 let target=state.profile.intake||'2027-04';const tasks=[{name:'目标与选校',start:6,end:5},{name:'核实招生要求',start:5,end:4},{name:'整理申请材料',start:4,end:3},{name:'学校 / COE 跟进',start:3,end:1},{name:'签证与出发准备',start:1,end:0}];
 body.innerHTML=`<div class="fields">${field('计划入学月份',`<input type="month" name="target" value="${target}" required>`)}${field('准备周期',select('lead',[['6','提前 6 个月'],['9','提前 9 个月'],['12','提前 12 个月']],'6'))}</div><div class="gantt"></div><div class="output-box" data-summary></div>${note('时间线是可调整的规划示意，不是学校官方截止日期，也不承诺 COE 或签证办理时长。先核对招生简章，再修改计划。')}`;
 const draw=()=>{target=body.querySelector('[name=target]').value||target;const lead=+body.querySelector('[name=lead]').value;const marks=Array.from({length:7},(_,i)=>monthsBefore(target,Math.round(lead*(6-i)/6)));body.querySelector('.gantt').innerHTML=`<div class="gantt-grid"><span class="gantt-cell">准备事项</span>${marks.map(m=>`<span class="gantt-cell">${m.slice(2).replace('-','.')}</span>`).join('')}${tasks.map((t,i)=>`<label class="gantt-label"><input type="checkbox" data-task="${i}">${t.name}</label><div class="gantt-track"><i class="gantt-fill" style="grid-column:${7-t.start}/${8-t.end}"></i></div>`).join('')}</div>`;body.querySelector('[data-summary]').textContent=`目标：${target.replace('-',' 年 ')} 月入学\n建议从 ${marks[0].replace('-',' 年 ')} 月开始筹备。\n点击左侧方框记录已完成的步骤。`;};body.querySelectorAll('select,input[type=month]').forEach(i=>i.onchange=draw);draw();body.addEventListener('change',e=>{if(e.target.dataset.task!==undefined)e.target.parentNode.nextElementSibling.style.opacity=e.target.checked?'.35':'1';});const a=action(btn('下载计划 CSV','secondary','data-export'));a.querySelector('button').onclick=()=>{const lead=+body.querySelector('[name=lead]').value;const csv='事项,建议开始月份,建议完成月份\n'+tasks.map(t=>`${t.name},${monthsBefore(target,Math.round(t.start*lead/6))},${monthsBefore(target,Math.round(t.end*lead/6))}`).join('\n');download('日本留学申请计划.csv','\uFEFF'+csv);toast('计划已下载');};
}
function profile({body,action,state,launch,toast}){
 let step=0;const data={goal:state.profile.goal||'',level:state.profile.level||'',city:state.profile.city||'',budget:state.profile.budget||15,intake:state.profile.intake||'2027-04',background:state.profile.background||''};
 const draw=()=>{body.replaceChildren();body.innerHTML=`<div class="wizard-progress">${Array.from({length:4},(_,i)=>`<i class="${i<=step?'done':''}"></i>`).join('')}</div><div class="wizard-content"></div>`;const content=body.querySelector('.wizard-content');if(step<3){const qs=[['你最想在日本完成什么？','不用是最终决定，之后都可以调整。','goal',['学习日语','升入大学 / 大学院','进入专门学校','探索生活与工作']],['现在的日语水平是？','用于安排准备节奏，不是能力评判。','level',['零基础','N5 / N4','N3','N2 / N1']],['想从哪座城市开始？','这个偏好会带进学校地点卡。','city',['东京','大阪','京都','还没决定']]][step];content.innerHTML=`<h3 class="wizard-title">${qs[0]}</h3><p class="wizard-help">${qs[1]}</p><div class="choice-grid">${qs[3].map(v=>btn(v,data[qs[2]]===v?'selected':'',`data-value="${v}"`)).join('')}</div>`;content.querySelectorAll('[data-value]').forEach(b=>b.onclick=()=>{data[qs[2]]=b.dataset.value;draw();});}else{content.innerHTML=`<h3 class="wizard-title">给计划一个大致范围</h3><div class="fields">${field('第一年预算上限 / 人民币',`<input type="range" name="budget" min="5" max="40" step="1" value="${data.budget}"><div class="range-row"><span>5 万</span><output>${data.budget} 万</output><span>40 万</span></div>`,true)}${field('计划入学月份',`<input type="month" name="intake" value="${data.intake}">`)}${field('一句话介绍自己',text('background',data.background,'例如：大四，准备升学'))}</div>`;content.oninput=e=>{data[e.target.name]=e.target.value;if(e.target.name==='budget')content.querySelector('output').textContent=e.target.value+' 万';};}
 const old=body.parentNode.querySelector('.card-actions');if(old)old.remove();const a=action(btn('上一步','secondary','data-back')+btn(step===3?'完成我的留学画像':'下一步 →','primary','data-next'));a.querySelector('[data-back]').disabled=step===0;a.querySelector('[data-back]').onclick=()=>{step--;draw();};a.querySelector('[data-next]').disabled=step<3&&!data[['goal','level','city'][step]];a.querySelector('[data-next]').onclick=()=>{if(step<3){step++;draw();}else{state.profile={...data};body.innerHTML=`<div class="tiny-tag" style="display:inline-block">已记录 · 本次页面会话</div><h3 class="wizard-title">你的计划，开始有轮廓了。</h3><div class="output-box">${esc(data.goal)} · ${esc(data.level)}\n城市：${esc(data.city)}\n预算上限：${esc(data.budget)} 万人民币\n入学：${esc(data.intake)}\n背景：${esc(data.background||'待补充')}</div>${note('信息仅留在本次页面内，刷新后不会保留。后续地点卡和申请时间线会带入你的选择。')}`;a.innerHTML=btn('按我的偏好看学校','primary','data-schools')+btn('展开我的申请计划','secondary','data-timeline');a.querySelector('[data-schools]').onclick=()=>launch('schools','按我的偏好看看学校');a.querySelector('[data-timeline]').onclick=()=>launch('timeline','按我的入学月份安排申请计划');toast('已带入本次对话');}};};draw();
}
function chart({body,follow,state,bus}){
 let mode='donut';body.innerHTML=`<div class="segmented">${btn('环形图','active','data-mode="donut"')}${btn('柱状图','','data-mode="bar"')}</div><div data-chart></div>${note('图表来自本次页面的预算试算值，不是市场统计。回到预算卡调整金额后，这张图会同步更新。')}`;const draw=()=>{const {parts,total}=calculateBudget(state.budget);const host=body.querySelector('[data-chart]');let offset=0;const stops=parts.map((p,i)=>{const a=offset;offset+=total?p.value/total*100:0;return `${colors[i]} ${a}% ${offset}%`;});const legend=`<div class="chart-legend">${parts.map((p,i)=>`<div><span><i style="display:inline-block;width:6px;height:6px;margin-right:8px;background:${colors[i]};border-radius:50%"></i>${p.label}</span><span>${yen(p.value)} · ${total?Math.round(p.value/total*100):0}%</span></div>`).join('')}</div>`;host.innerHTML=mode==='donut'?`<div class="chart-layout"><div class="donut" style="background:conic-gradient(${stops.join(',')})" role="img" aria-label="预算占比环形图"><span>${yen(total)}</span></div>${legend}</div>`:`<div class="bar-chart" role="img" aria-label="预算分类柱状图">${parts.map((p,i)=>`<div><i style="height:${p.value/Math.max(1,...parts.map(p=>p.value))*125}px;background:${colors[i]}"></i><span>${p.label}</span></div>`).join('')}</div>${legend}`;};body.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;body.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));draw();});bus.addEventListener('budget',draw);draw();follow([['修改预算数字','budget']]);
}
const lexicon={
 '敷金':{reading:'しききん · shikikin',meaning:'押金；租房时用于担保租约义务的一笔费用。',jp:'敷金は家賃の一か月分です。',zh:'押金是一个月的房租。',tip:'是否退还、扣除哪些费用，需要看实际租约。'},
 '礼金':{reading:'れいきん · reikin',meaning:'礼金；日本租赁中可能出现的一次性费用。',jp:'この部屋は礼金なしです。',zh:'这个房间不收礼金。',tip:'不要把礼金与押金混为一谈，费用和条款需逐项确认。'},
 '出願':{reading:'しゅつがん · shutsugan',meaning:'提出申请；在学校语境中通常指提交入学申请。',jp:'出願期間を確認してください。',zh:'请确认申请期间。',tip:'出願期間＝可递交申请的时间范围。'},
 '在留資格':{reading:'ざいりゅうしかく · zairyū shikaku',meaning:'在留资格；与在日本可从事的活动相关的身份类别。',jp:'在留資格は「留学」です。',zh:'在留资格是“留学”。',tip:'日常口语常与“签证”混用，办理时应区分。'},
 '奨学金':{reading:'しょうがくきん · shōgakukin',meaning:'奖学金或助学资金。',jp:'奨学金に応募したいです。',zh:'我想申请奖学金。',tip:'有些制度需要偿还，申请前确认给付型还是贷与型。'}
};
function dictionary({body,action,state,query,toast}){
 let word=Object.keys(lexicon).find(w=>query.includes(w))||'敷金';body.innerHTML=`<div class="fields">${field('查一个日文词',text('word',word,'敷金 / 礼金 / 出願'),true)}</div><div class="step-pills" style="margin-top:15px">${Object.keys(lexicon).map(w=>btn(w,'',`data-word="${w}"`)).join('')}</div><div data-definition></div><div class="saved-words"></div>`;
 const refresh=()=>{word=body.querySelector('[name=word]').value.trim();const d=lexicon[word],h=body.querySelector('[data-definition]');if(!d){h.innerHTML='<div class="empty-state">预览词库暂未收录这个词。先试试上面的 5 个留学生活词；接入模型后可扩展自由查词。</div>';return;}h.innerHTML=`<div class="word-hero">${esc(word)}</div><div class="reading">${d.reading}</div><p class="meaning">${d.meaning}</p><div class="example">${d.jp}<small>${d.zh}</small></div><p class="card-note"><span class="word-tooltip" tabindex="0" data-tip="${esc(d.tip)}">晓 tip · 移到这里看一点补充</span></p>`;};body.querySelector('[name=word]').oninput=refresh;body.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{body.querySelector('[name=word]').value=b.dataset.word;refresh();});const a=action(btn('收进我的单词卡','primary','data-save')+btn('复制词条','secondary','data-copy'));a.querySelector('[data-save]').onclick=()=>{if(!lexicon[word])return toast('先选择一个已收录词语');state.words.add(word);body.querySelector('.saved-words').textContent='本次已收集：'+[...state.words].join(' · ');toast('单词已收好');};a.querySelector('[data-copy]').onclick=()=>{const d=lexicon[word];if(d)copy(`${word}（${d.reading}）\n${d.meaning}\n${d.jp}\n${d.zh}`,toast);};refresh();
}
async function copy(value,toast){try{await navigator.clipboard.writeText(value);toast('已复制');}catch{toast('复制不可用，请选中文字复制');}}
function download(filename,value){const url=URL.createObjectURL(new Blob([value],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
